import json
from collections import Counter

# Load samples
samples = []
with open("output/exp003_wnut17_eval/samples.jsonl") as f:
    for line in f:
        if line.strip():
            samples.append(json.loads(line))

print(f"Total instances: {len(samples)}")

# Compute per-instance F1
def entity_f1(pred_ents, gold_ents):
    pred_set = {(e["start"], e["end"], e["type"]) for e in pred_ents}
    gold_set = {(e["start"], e["end"], e["type"]) for e in gold_ents}
    tp = len(pred_set & gold_set)
    fp = len(pred_set - gold_set)
    fn = len(gold_set - pred_set)
    if tp + fp == 0: p = 0
    else: p = tp / (tp + fp)
    if tp + fn == 0: r = 0
    else: r = tp / (tp + fn)
    if p + r == 0: return 0.0
    return 2 * p * r / (p + r)

# Categorize
gold_empty_count = 0
f1_zero_with_gold = 0
f1_zero_model_empty = 0
f1_zero_type_mismatch = 0
f1_zero_span_mismatch = 0
f1_zero_both_mismatch = 0
f1_positive = 0

f1_zero_examples = []

for inst in samples:
    gold = inst["gold"]
    greedy = inst["greedy"]
    gold_ents = gold.get("entities", [])
    greedy_ents = greedy.get("entities", [])

    if len(gold_ents) == 0:
        gold_empty_count += 1
        continue

    f1 = entity_f1(greedy_ents, gold_ents)

    if f1 == 0:
        f1_zero_with_gold += 1
        if len(greedy_ents) == 0:
            f1_zero_model_empty += 1
        else:
            # Check what kind of mismatch
            gold_set = {(e["start"], e["end"], e["type"]) for e in gold_ents}
            pred_set = {(e["start"], e["end"], e["type"]) for e in greedy_ents}
            # Check span-only match (ignoring type)
            gold_spans = {(e["start"], e["end"]) for e in gold_ents}
            pred_spans = {(e["start"], e["end"]) for e in greedy_ents}
            span_overlap = gold_spans & pred_spans
            # Check type-only match (ignoring span)
            gold_types = Counter(e["type"] for e in gold_ents)
            pred_types = Counter(e["type"] for e in greedy_ents)

            if span_overlap:
                f1_zero_type_mismatch += 1
            else:
                f1_zero_span_mismatch += 1

        if len(f1_zero_examples) < 15:
            f1_zero_examples.append({
                "id": inst["id"],
                "text": inst["text"][:120],
                "gold_ents": gold_ents,
                "greedy_ents": greedy_ents[:5],
                "n_greedy": len(greedy_ents),
            })
    else:
        f1_positive += 1

print(f"\n--- Instance Breakdown ---")
print(f"Gold empty: {gold_empty_count}")
print(f"F1=0 (gold non-empty): {f1_zero_with_gold}")
print(f"  - model output empty: {f1_zero_model_empty}")
print(f"  - span mismatch (model predicted but wrong spans): {f1_zero_span_mismatch}")
print(f"  - type mismatch (correct span but wrong type): {f1_zero_type_mismatch}")
print(f"F1>0: {f1_positive}")

print(f"\n--- F1=0 Examples (first 15) ---")
for ex in f1_zero_examples:
    print(f"\n[{ex['id']}] {ex['text']}...")
    print(f"  GOLD ({len(ex['gold_ents'])}): {json.dumps(ex['gold_ents'], ensure_ascii=False)}")
    print(f"  PRED ({ex['n_greedy']}): {json.dumps(ex['greedy_ents'], ensure_ascii=False)}")
